import{_ as a,o as d,c as o,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 7 章 计划模式与长任务执行","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md"}'),r={name:"bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md"};function s(l,t,n,i,h,p){return d(),o("div",null,[...t[0]||(t[0]=[e(`<h1 id="第-7-章-计划模式与长任务执行" tabindex="-1">第 7 章 计划模式与长任务执行 <a class="header-anchor" href="#第-7-章-计划模式与长任务执行" aria-label="Permalink to &quot;第 7 章 计划模式与长任务执行&quot;">​</a></h1><blockquote><p>本章目标：掌握计划模式的适用场景、体验与纪律。学会把大任务拆成可检查的步骤，给重要任务加一道&quot;先想后做&quot;的闸门。<strong>改动越大，这道闸门越值钱。</strong></p></blockquote><h2 id="_7-1-什么时候需要计划模式" tabindex="-1">7.1 什么时候需要计划模式 <a class="header-anchor" href="#_7-1-什么时候需要计划模式" aria-label="Permalink to &quot;7.1 什么时候需要计划模式&quot;">​</a></h2><p>小任务（写一段代码、改一个文件）不需要计划，直接干。但遇到这些情况，你应该让我<strong>先进计划模式</strong>：</p><h3 id="_7-1-1-四类必须计划的场景" tabindex="-1">7.1.1 四类必须计划的场景 <a class="header-anchor" href="#_7-1-1-四类必须计划的场景" aria-label="Permalink to &quot;7.1.1 四类必须计划的场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景特征</th><th>例子</th><th>为什么需要计划</th></tr></thead><tbody><tr><td>跨多个文件/步骤</td><td>重构项目日志模块</td><td>牵一发动全身</td></tr><tr><td>有顺序依赖</td><td>B 依赖 A 的结果</td><td>顺序错了全白干</td></tr><tr><td>影响面大</td><td>数据库迁移、接口改造</td><td>风险高，需先评估</td></tr><tr><td>你希望先看方案</td><td>大型交付物</td><td>方向对了才动手</td></tr></tbody></table><h3 id="_7-1-2-判断口诀" tabindex="-1">7.1.2 判断口诀 <a class="header-anchor" href="#_7-1-2-判断口诀" aria-label="Permalink to &quot;7.1.2 判断口诀&quot;">​</a></h3><blockquote><p><strong>&quot;这件事做完会不会后悔？&quot;</strong> 如果做错代价大、返工成本高，就先进计划模式。反之，小任务直接干。</p></blockquote><h2 id="_7-2-计划模式是什么体验" tabindex="-1">7.2 计划模式是什么体验 <a class="header-anchor" href="#_7-2-计划模式是什么体验" aria-label="Permalink to &quot;7.2 计划模式是什么体验&quot;">​</a></h2><h3 id="_7-2-1-完整流程" tabindex="-1">7.2.1 完整流程 <a class="header-anchor" href="#_7-2-1-完整流程" aria-label="Permalink to &quot;7.2.1 完整流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;我想重构项目里的日志模块，先做个计划&quot;</span></span>
<span class="line"><span>我：进入计划模式</span></span>
<span class="line"><span>  → 只读：浏览代码结构、搜索相关调用（不动任何文件）</span></span>
<span class="line"><span>  → 分析：找出改动点、风险点、影响范围</span></span>
<span class="line"><span>  → 产出：一份实施计划（步骤、顺序、验收方式）</span></span>
<span class="line"><span>你：审阅计划，说&quot;执行&quot;或&quot;调整&quot;</span></span>
<span class="line"><span>我：退出计划模式，按计划逐步执行，每步报告进度</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">关键特性</p><p><strong>计划模式下我只读不改。</strong> 你看完方案再放行，避免我&quot;先斩后奏&quot;。这是计划模式与普通执行最本质的区别。</p></div><h3 id="_7-2-2-计划模式做了什么" tabindex="-1">7.2.2 计划模式做了什么 <a class="header-anchor" href="#_7-2-2-计划模式做了什么" aria-label="Permalink to &quot;7.2.2 计划模式做了什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>说明</th><th>工具</th></tr></thead><tbody><tr><td>浏览现状</td><td>了解任务涉及的代码/文件</td><td>Read、Glob</td></tr><tr><td>搜索关联</td><td>找出所有受影响的地方</td><td>Grep</td></tr><tr><td>风险分析</td><td>评估改动的影响面与风险点</td><td>分析</td></tr><tr><td>方案设计</td><td>拆步骤、定顺序、定验收</td><td>设计</td></tr></tbody></table><h2 id="_7-3-好计划长什么样" tabindex="-1">7.3 好计划长什么样 <a class="header-anchor" href="#_7-3-好计划长什么样" aria-label="Permalink to &quot;7.3 好计划长什么样&quot;">​</a></h2><p>一份值得放行的计划，包含四个要素：</p><table tabindex="0"><thead><tr><th>要素</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>步骤</strong></td><td>拆成可执行的顺序步骤</td><td>1. 读现状 2. 改接口 3. 改调用方 4. 跑测试</td></tr><tr><td><strong>顺序</strong></td><td>明确依赖关系</td><td>第 4 步依赖第 2、3 步完成</td></tr><tr><td><strong>风险</strong></td><td>可能踩的坑</td><td>接口变更会影响 3 个模块</td></tr><tr><td><strong>验收</strong></td><td>每一步怎么算完成</td><td>测试通过、无回归</td></tr></tbody></table><h3 id="_7-3-1-好计划-vs-坏计划" tabindex="-1">7.3.1 好计划 vs 坏计划 <a class="header-anchor" href="#_7-3-1-好计划-vs-坏计划" aria-label="Permalink to &quot;7.3.1 好计划 vs 坏计划&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>坏计划</th><th>好计划</th></tr></thead><tbody><tr><td>粒度</td><td>步骤太大，无法检查</td><td>每步 10 分钟内可验证</td></tr><tr><td>顺序</td><td>依赖关系含糊</td><td>明确谁先谁后、谁等谁</td></tr><tr><td>风险</td><td>只字不提</td><td>列出风险 + 应对方案</td></tr><tr><td>验收</td><td>&quot;做完就行&quot;</td><td>每步都有可检查的验收点</td></tr></tbody></table><h2 id="_7-4-执行中的进度管理" tabindex="-1">7.4 执行中的进度管理 <a class="header-anchor" href="#_7-4-执行中的进度管理" aria-label="Permalink to &quot;7.4 执行中的进度管理&quot;">​</a></h2><p>执行长任务时，我会：</p><ul><li>每完成一步，更新计划进度状态（计划工具可视化进度）；</li><li>遇到偏离计划的情况，<strong>先说明再行动</strong>；</li><li>需要你决策的节点，<strong>停下来问你</strong>，不擅自做主。</li></ul><h3 id="_7-4-1-你的三大权力" tabindex="-1">7.4.1 你的三大权力 <a class="header-anchor" href="#_7-4-1-你的三大权力" aria-label="Permalink to &quot;7.4.1 你的三大权力&quot;">​</a></h3><ol><li><strong>暂停权</strong>：随时打断——&quot;先停在第 2 步，我要看一下。&quot;</li><li><strong>改道权</strong>：发现方向不对——&quot;第 3 步换个做法。&quot;</li><li><strong>验收权</strong>：每步都可以要求先看产物，满意再继续。</li></ol><div class="tip custom-block"><p class="custom-block-title">协作建议</p><p><strong>长任务的检查节奏：每 1~2 步检查一次，而不是最后才看。</strong> 越早发现偏差，返工成本越低。</p></div><h2 id="_7-5-计划模式的纪律" tabindex="-1">7.5 计划模式的纪律 <a class="header-anchor" href="#_7-5-计划模式的纪律" aria-label="Permalink to &quot;7.5 计划模式的纪律&quot;">​</a></h2><ul><li>✅ 模式内不写文件，只读与规划；</li><li>✅ 计划要能被人看懂和审阅；</li><li>✅ 计划获批后才动手；</li><li>✅ 每步可检查、可回退；</li><li>❌ 不要把计划模式当成&quot;拖延模式&quot;——目标仍然是尽快产出可验收的结果。</li></ul><h3 id="_7-5-1-计划的两种结局" tabindex="-1">7.5.1 计划的两种结局 <a class="header-anchor" href="#_7-5-1-计划的两种结局" aria-label="Permalink to &quot;7.5.1 计划的两种结局&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>计划被放行 → 按计划执行 → 每步汇报 → 交付验收</span></span>
<span class="line"><span>计划被否决 → 你指出问题 → 我修订计划 → 再审阅</span></span></code></pre></div><p><strong>计划被否决不是失败</strong>，恰恰是计划模式的价值——在动手前花小代价，避免动手后花大代价。</p><h2 id="_7-6-计划模式-×-其他章节的配合" tabindex="-1">7.6 计划模式 × 其他章节的配合 <a class="header-anchor" href="#_7-6-计划模式-×-其他章节的配合" aria-label="Permalink to &quot;7.6 计划模式 × 其他章节的配合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组合</th><th>用法</th><th>参考</th></tr></thead><tbody><tr><td>计划 + 四要素</td><td>用四要素描述任务，进计划模式细化</td><td>第 2 章</td></tr><tr><td>计划 + 记忆</td><td>把计划中的关键决策存入记忆</td><td>第 6 章</td></tr><tr><td>计划 + 团队</td><td>大计划拆成子任务分派给团队</td><td>第 8、16 章</td></tr><tr><td>计划 + Skill</td><td>执行阶段调用 Skill 保证质量</td><td>第 5、17 章</td></tr></tbody></table><h2 id="_7-7-本章练习" tabindex="-1">7.7 本章练习 <a class="header-anchor" href="#_7-7-本章练习" aria-label="Permalink to &quot;7.7 本章练习&quot;">​</a></h2><ol><li>给我一个中型任务（比如&quot;把 docs 目录整理成统一格式&quot;），要求先进计划模式。</li><li>审阅我给的计划：四要素（步骤/顺序/风险/验收）是否齐全？提出一处调整。</li><li>放行后观察：执行是否严格按步骤走？每步是否可检查？</li><li>模拟一次&quot;中途暂停&quot;：在第 2 步叫停，验证暂停权是否生效。</li></ol><hr><blockquote><p>小结：计划模式 = <strong>给重要任务加一道&quot;先想后做&quot;的闸门</strong>。计划不是拖延，而是用最小的成本试错——<strong>改动越大，这道闸门越值钱。</strong> 下一章，我们把复杂度交给团队：AI 团队。</p></blockquote>`,36)])])}const b=a(r,[["render",s]]);export{c as __pageData,b as default};
